function balanceOf(address account) external view returns (uint) {
        return balances[account];
    }

function allowance(address account, address spender) external view returns (uint) {
        return allowances[account][spender];
    }

function getReward() public nonReentrant updateReward(msg.sender) {
        uint256 reward = rewards[msg.sender];
        if (reward > 0) {
            rewards[msg.sender] = 0;
            _transferTokens(address(this), msg.sender, reward);
            emit Earned(msg.sender, reward);
        }
    }

function getRewardForDuration() external view returns (uint) {
        return rewardRate * DURATION;
    }

function lastTimeRewardApplicable() public view returns (uint) {
        return Math.min(block.timestamp, periodFinish);
    }

function rewardPerToken() public view returns (uint) {
        if (stakedSupply == 0) {
            return rewardPerTokenStored;
        }
        return
            rewardPerTokenStored +
                ((lastTimeRewardApplicable() - 
                lastUpdateTime) * 
                rewardRate * 1e18 / stakedSupply);
    }

function rewards(address account) external view returns (uint) {
        return rewards[account];
    }

function userRewardPerTokenPaid(address account) external view returns (uint) {
        return userRewardPerTokenPaid[account];
    }

function stakes(address account) external view returns (uint) {
        return stakes[account];
    }

function totalSupply() external view returns (uint) {
        return totalSupply;
    }

function stakedSupply() external view returns (uint) {
        return stakedSupply;
    }

function rewardRate() external view returns (uint) {
        return rewardRate;
    }
